// Cross-platform coverage ledger.
//
// The workflow used to name its test files by hand on an ubuntu-only step:
// new tests never entered CI, and this ledger claimed `matrix` coverage that
// no step produced. Now the workflow runs scripts/test-all.mjs — the list is
// generated by the same discovery this file uses, so nothing can drift out of
// CI silently. What remains to prove is that the step really runs on every
// OS the matrix declares, and that every discovered test is classified.
//
//   matrix    — run by scripts/test-all.mjs on every matrix OS
//   EXCLUDED  — a stated, checkable reason it cannot run there
import { readFileSync, existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { eq, ok, summary } from './test-util.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..', '..');
const workflow = path.join(root, '.github', 'workflows', 'test-matrix.yml');

// What counts as a gated test file, and which need a runtime or a Linux pty,
// comes from the same module the runner uses — one answer, three readers.
import { discoverTests, NEEDS_RUNTIME, NEEDS_LINUX_PTY, PLATFORM_EXCLUDES } from '../../scripts/discover-tests.mjs';

ok(existsSync(workflow), 'test-matrix.yml exists');
const yml = readFileSync(workflow, 'utf8');

// 1. The CI matrix declares the three OSes the ledger claims.
const osDecl = /os:\s*\[([^\]]+)\]/.exec(yml)?.[1].split(',').map(s => s.trim()) ?? [];
for (const os of ['ubuntu-latest', 'windows-latest', 'macos-latest'])
  ok(osDecl.includes(os), `test-matrix.yml matrix declares ${os}`);

// 2. The unit step runs the discovery-driven runner, on every matrix OS —
//    no `if:` gate, no hand-named file list (a named list is how tests
//    drifted out of CI last time).
const stepBlocks = yml.split(/\n(?= +- )/).filter(b => /\brun:/.test(b));
const unitStep = stepBlocks.find(b => /run:\s*node scripts\/test-all\.mjs/.test(b));
ok(unitStep != null, 'a CI step runs scripts/test-all.mjs (discovery-driven suite)');
if (unitStep) {
  ok(!/^\s+if:/m.test(unitStep), 'the unit-test step has no `if:` — it runs on every matrix OS');
}
ok(!/node --test\s+\S*test\S*\.mjs/.test(yml),
  'no hand-named `node --test` list remains (it drifted out of sync before)');

// 3. Classify every discovered test exactly once. The runner and the ledger
//    share NEEDS_RUNTIME / NEEDS_LINUX_PTY, so "excluded with a reason" here
//    is the same set the runner skips — they cannot disagree.
const EXCLUDED = new Map([
  ...[...NEEDS_RUNTIME].map(f => [f, 'drives a real ZCode runtime process (--live only)']),
  ...[...NEEDS_LINUX_PTY].map(f => [f, 'needs util-linux script(1) pty (-qfec); Linux only']),
]);

const discovered = discoverTests(root)
  .map(f => path.relative(root, f).split(path.sep).join('/'))
  .sort();
ok(discovered.length > 0, `discovered ${discovered.length} test file(s)`);

for (const rel of discovered) {
  const base = path.basename(rel);
  const buckets = [EXCLUDED.has(base) ? 'excluded' : 'matrix'];
  eq(buckets.length, 1, `${rel} is in exactly one bucket (${buckets[0]})`);
}

// 4. No stale bookkeeping: every excluded name still resolves to a real test.
const discoveredBases = new Set(discovered.map(f => path.basename(f)));
for (const file of EXCLUDED.keys())
  ok(discoveredBases.has(file), `${file} excluded in the ledger still exists`);

// 5. Every exclusion states a reason.
for (const [file, reason] of EXCLUDED)
  ok(typeof reason === 'string' && reason.trim().length > 0, `${file} exclusion states a reason`);

// 6. Per-OS exclusions — the file still runs everywhere else, so the shape is
//    {file, os, reason}: a real discovered test, a real platform, a concrete
//    reason, and never a second way to skip what NEEDS_* already excludes.
const MATRIX_PLATFORMS = new Set(['linux', 'darwin', 'win32']);
for (const { file, os, reason } of PLATFORM_EXCLUDES) {
  ok(discoveredBases.has(file), `${file} platform-excluded on ${os} still exists`);
  ok(MATRIX_PLATFORMS.has(os), `${file} platform exclusion names a matrix os (${os})`);
  ok(typeof reason === 'string' && reason.trim().length > 0, `${file} ${os} exclusion states a reason`);
  ok(!EXCLUDED.has(file), `${file} is both fully excluded and ${os}-excluded — pick one`);
}
const perOsSeen = new Set();
for (const { file, os } of PLATFORM_EXCLUDES) {
  ok(!perOsSeen.has(`${file}:${os}`), `${file} has a duplicate ${os} exclusion`);
  perOsSeen.add(`${file}:${os}`);
}
for (const file of new Set(PLATFORM_EXCLUDES.map(e => e.file)))
  ok(PLATFORM_EXCLUDES.filter(e => e.file === file).length < MATRIX_PLATFORMS.size,
    `${file} is excluded on every OS — that is what NEEDS_* is for`);

summary('xplat-coverage');
